volatile std::uint64_t observation=0;
template<class U>void bench(int kind,int n,int k,int reps){
 std::vector<U> data;if(kind==2||kind==3||kind==6){std::uint64_t state=80491001;const U allowed=first_combination<U>(n);data.resize(16384);for(std::size_t i=0;i<data.size();++i){state^=state<<13;state^=state>>7;state^=state<<17;data[i]=static_cast<U>(state)&allowed;}data[0]=0;data[1]=allowed;if(n>0)data[2]=static_cast<U>(U{1}<<(n-1));}
 std::uint64_t sum=0;const auto start=std::clock();std::atomic_signal_fence(std::memory_order_seq_cst);
 for(int rep=0;rep<reps;++rep){
  if(kind==0)for_each_combination<U>(n,k,[&](U v){sum+=v;});
  else if(kind==1)for_each_combination<U>(n,k,[&](U v){sum^=std::uint64_t(v)+UINT64_C(0x9e3779b97f4a7c15)+(sum<<6)+(sum>>2);});
  else if(kind==2)for(U v:data)sum+=next_combination(v);
  else if(kind==3)for(U v:data){const bool ok=next_combination(v,n);sum+=v+std::uint64_t(ok);}
  else if(kind==6)for(U v:data)sum+=next_combination(static_cast<int>(std::uint32_t(v)&UINT32_C(0x7fffffff)));
  else{U v=first_combination<U>(k);const U last=last_combination<U>(n,k);if(kind==4){for(;;){sum+=v;if(v==last)break;v=next_combination(v);}}else{do{sum+=v;}while(next_combination(v,n));}}
  observation=sum;
 }
 std::atomic_signal_fence(std::memory_order_seq_cst);const auto ns=std::uintmax_t(std::clock()-start)*1000000000/CLOCKS_PER_SEC;std::printf("%ju %ju\n",ns,std::uintmax_t(sum));
}
int main(int argc,char**argv){if(argc!=6)return 2;const int w=std::atoi(argv[1]),kind=std::atoi(argv[2]),n=std::atoi(argv[3]),k=std::atoi(argv[4]),reps=std::atoi(argv[5]);if(w==8)bench<std::uint8_t>(kind,n,k,reps);else if(w==16)bench<std::uint16_t>(kind,n,k,reps);else if(w==32)bench<std::uint32_t>(kind,n,k,reps);else bench<std::uint64_t>(kind,n,k,reps);}

