// SPDX-License-Identifier: CC0-1.0
#include <array>
#include <cstdint>
#include <iostream>
#include <limits>
int main() {
    int n{}, m{}; std::int64_t modulus{};
    if (!(std::cin >> n >> m >> modulus) || n < 2 || n > 8 || modulus <= 0) return 2;
    std::array<std::array<std::int64_t, 8>, 8> weight{};
    std::array<std::array<bool, 8>, 8> exists{};
    for (int i = 0; i < m; ++i) {
        int a{}, b{}; std::int64_t w{}; std::cin >> a >> b >> w; --a; --b;
        if (a < 0 || b < 0 || a >= n || b >= n || a == b || w < 0 || w >= modulus || exists[a][b]) return 3;
        exists[a][b] = exists[b][a] = true; weight[a][b] = weight[b][a] = w;
    }
    std::uint64_t sequences = 1;
    for (int i = 0; i < n - 2; ++i) sequences *= static_cast<std::uint64_t>(n);
    std::int64_t answer = modulus;
    // 各ラベル付き木をPruefer列から1回ずつ復元する。辺部分集合やDSUは使わない。
    for (std::uint64_t code = 0; code < sequences; ++code) {
        auto digits = code; std::array<int, 6> sequence{}; std::array<int, 8> degree{};
        for (int i = 0; i < n; ++i) degree[i] = 1;
        for (int i = 0; i < n - 2; ++i) { const int value = static_cast<int>(digits % n); digits /= n; sequence[i] = value; ++degree[value]; }
        bool valid = true; std::int64_t sum = 0;
        for (int i = 0; i < n - 2; ++i) {
            int leaf = 0; while (degree[leaf] != 1) ++leaf;
            const int other = sequence[i];
            if (!exists[leaf][other]) { valid = false; break; }
            sum += weight[leaf][other]; --degree[leaf]; --degree[other];
        }
        if (!valid) continue;
        int first = -1, second = -1;
        for (int i = 0; i < n; ++i) if (degree[i] == 1) { if (first < 0) first = i; else second = i; }
        if (!exists[first][second]) continue;
        sum += weight[first][second];
        const auto residue = sum % modulus;
        if (residue < answer) answer = residue;
    }
    std::cout << answer << '\n';
}

